def standarisasi_kolom(X):
    n, d = len(X), len(X[0])
    hasil = [[0.0] * d for _ in range(n)]
    for j in range(d):
        kol = [r[j] for r in X]
        m = sum(kol) / n
        sd = (sum((v - m) ** 2 for v in kol) / (n - 1)) ** 0.5
        for i in range(n):
            hasil[i][j] = 0.0 if sd == 0 else round((kol[i] - m) / sd, 4) + 0.0
    return hasil

